    candidates.append(neh_bottleneck_only())

    # Evaluate all candidates
    best_overall = None
    best_overall_ms = float('inf')
    for cand in candidates:
        ms = compute_makespan(cand)
        if ms < best_overall_ms:
            best_overall_ms = ms
            best_overall = cand[:]

    # Apply local search to top candidates
    candidate_scores = [(compute_makespan(c), c) for c in candidates]
    candidate_scores.sort(key=lambda x: x[0])

    # Apply insertion LS to best candidates
    top_k = min(3, len(candidate_scores))
    threshold = candidate_scores[0][0] * 1.15

    for ms_c, cand in candidate_scores[:top_k]:
        if ms_c <= threshold:
            sol, ms_s = local_search_insertion(cand, max_ls_iter)
            if ms_s < best_overall_ms:
                best_overall_ms = ms_s
                best_overall = sol[:]

    # Apply swap then insertion on best
    sol2, ms2 = local_search_swap(best_overall, max_ls_iter)
    if ms2 < best_overall_ms:
        best_overall_ms = ms2
        best_overall = sol2[:]

    sol3, ms3 = local_search_insertion(best_overall, max_ls_iter)
    if ms3 < best_overall_ms:
        best_overall_ms = ms3
        best_overall = sol3[:]

    # ILS phase
    random.seed(42)
    ils_iters = max(3, min(25, 500 // n))
    current = best_overall[:]
    current_ms = best_overall_ms

    for it in range(ils_iters):
        perturbed = current[:]

        if it % 3 == 0 and n >= 8:
            # Double-bridge style perturbation (4-opt)
            positions = sorted(random.sample(range(1, n), min(3, n - 1)))
            p1, p2, p3 = positions[0], positions[1], positions[2]
            if p1 < p2 < p3 < n:
                perturbed = current[:p1] + current[p2:p3] + current[p1:p2] + current[p3:]
            else:
                i, j = random.sample(range(n), 2)
                perturbed[i], perturbed[j] = perturbed[j], perturbed[i]
        elif it % 3 == 1 and n > 4:
            # Random reinsertion perturbation
            num_perturb = random.randint(2, min(4, max(2, n // 3)))
            positions = sorted(random.sample(range(n), num_perturb), reverse=True)
            jobs_to_reinsert = [perturbed[p] for p in positions]
            for p in positions:
                perturbed.pop(p)
            for job in jobs_to_reinsert:
                pos = random.randint(0, len(perturbed))
                perturbed.insert(pos, job)
        else:
            # Swap perturbation
            if n >= 4:
                pairs = random.randint(2, min(3, n // 2))
                for _ in range(pairs):
                    i, j = random.sample(range(n), 2)
                    perturbed[i], perturbed[j] = perturbed[j], perturbed[i]
            else:
                i, j = random.sample(range(n), 2)
                perturbed[i], perturbed[j] = perturbed[j], perturbed[i]

        sol, ms = local_search_insertion(perturbed, max(1, max_ls_iter // 2))

        if ms < best_overall_ms:
            best_overall_ms = ms
            best_overall = sol[:]
            current = sol[:]
            current_ms = ms
        elif ms < current_ms * 1.05:
            current = sol[:]
            current_ms = ms

    # Final polish: swap then insertion
    sol_f, ms_f = local_search_swap(best_overall, max_ls_iter)
    if ms_f < best_overall_ms:
        best_overall_ms = ms_f
        best_overall = sol_f[:]

    sol_f2, ms_f2 = local_search_insertion(best_overall, max_ls_iter)
    if ms_f2 < best_overall_ms:
        best_overall_ms = ms_f2
        best_overall = sol_f2[:]

    # One more swap pass
    sol_f3, ms_f3 = local_search_swap(best_overall, max_ls_iter)
    if ms_f3 < best_overall_ms:
        best_overall_ms = ms_f3
        best_overall = sol_f3[:]

    return best_overall
